@Override
    public int read() throws IOException {
        if (position < cache.size()) {
            // Reading from cache (replay mode)
            int b = cache.readAt(position);
            if (b != -1) {
                position++;
            }
            return b;
        }

        if (sourceExhausted) {
            return -1;
        }

        // Reading new byte from source
        int b = source.read();
        if (b == -1) {
            sourceExhausted = true;
            return -1;
        }

        cache.append(b);
        position++;
        return b;
    }

